(function(){'use strict';const $=id=>document.getElementById(id),status=$('account-status');let factorId='',busy=false,otpEmail='',resendAt=0,ready=false;function resendState(){const seconds=Math.max(0,Math.ceil((resendAt-Date.now())/1000));$('account-otp-resend').disabled=busy||!ready||seconds>0;$('account-otp-resend').textContent=seconds?'Resend code in '+seconds+'s':'Resend code'}setInterval(resendState,1000);
async function api(action,data){const r=await fetch('/api/account/'+action,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(20000)});let result;try{result=await r.json()}catch{throw Error('Account access is temporarily unavailable. Please try again later.')}if(!r.ok)throw Error(result.error||'This action could not be completed.');return result}
async function load(){const entering=$('account-profile').hidden;let r;try{r=await api('session');}catch(e){for(const id of ['account-profile','account-admin','account-security'])$(id).hidden=true;$('account-login').hidden=true;$('account-guest').hidden=false;throw Error('Access could not be verified. Keep any inquiry tab open, then use Check access again. '+e.message);}$('account-login').hidden=r.signedIn;$('account-profile').hidden=!r.signedIn;$('account-security').hidden=!r.signedIn;$('account-admin').hidden=!r.operator;if(!r.signedIn){$('account-guest').hidden=false;status.textContent='Enter your approved account email to receive a sign-in code.';return}status.textContent='Signed in. Only account and plan information is stored.';$('account-identity').textContent=r.email;$('account-id').textContent=r.accountId;$('account-plans').textContent=r.access.length?'Active plans: '+r.access.map(x=>({essential:'Inquiry Essential',professional:'Inquiry Professional',advanced:'Inquiry Advanced',institutional:'Institutional Plus',enterprise:'Government / Enterprise',knowledge:'Expert Knowledge'}[x.plan]||x.plan)).join(', '):'No active verified plan is confirmed. Review access and renewal options below.';$('account-open').hidden=!r.access.some(x=>x.guided);renderRenewals(r.access);$('account-getting-started').hidden=!r.access.some(x=>x.guided);$('account-product-scope').textContent='Included now: guided questions, contextual editable drafts and browser-only timelines. Your plan does not create shared case storage or authorise the software to make Committee decisions.';$('account-pending-help').hidden=r.access.length>0;$('account-guest').hidden=r.access.length>0;$('account-access-title').textContent=r.access.some(x=>x.guided)?'Your inquiry workspace is ready':'Your account and access';factorId=r.factors[0]?.id||'';$('account-enrol').hidden=!!factorId;$('account-mfa').hidden=false;$('account-otp-pending').hidden=true;$('account-otp-verify').reset();if(entering){$('account-access-title').tabIndex=-1;$('account-access-title').focus();}}
function renderRenewals(access){const list=$('account-renewals');list.replaceChildren();const names={essential:'Inquiry Essential',professional:'Inquiry Professional',advanced:'Inquiry Advanced',institutional:'Institutional Plus',enterprise:'Government / Enterprise',knowledge:'Expert Knowledge'};if(!access.length){const p=document.createElement('p');p.textContent='No active access is confirmed. Contact support to check purchase verification, future start dates or renewal. This screen cannot distinguish those reasons.';list.append(p);const a=document.createElement('a');a.className='btn btn-light';a.href='mailto:training@thecosmicenergizers.com?subject=Navigator%20access%20or%20renewal%20enquiry';a.textContent='Ask about access or renewal';list.append(a);return;}for(const item of access){const end=new Date(item.ends_at);if(!Number.isFinite(end.getTime()))continue;const milliseconds=end-Date.now(),remaining=Math.ceil(milliseconds/86400000),alarm=milliseconds>7*86400000?'-P7D':milliseconds>86400000?'-P1D':milliseconds>3600000?'-PT1H':milliseconds>300000?'-PT5M':'PT0S',row=document.createElement('article'),title=document.createElement('h4'),p=document.createElement('p'),a=document.createElement('a'),button=document.createElement('button');row.className='account-renewal'+(remaining<=30?' renewal-due':'');title.textContent=names[item.plan]||item.plan;p.textContent='Access ends '+end.toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'long',timeStyle:'short'})+' IST (exclusive). '+(remaining<=7?'Ends within seven days — arrange renewal now.':remaining<=30?'Ends within thirty days — plan your renewal.':'Active access.');a.href='mailto:training@thecosmicenergizers.com?subject='+encodeURIComponent('Navigator '+(names[item.plan]||item.plan)+' renewal enquiry');a.className='btn btn-light';a.textContent='Request renewal details';button.type='button';button.className='btn btn-light';button.textContent='Download expiry reminder';button.onclick=()=>{const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//POSH Navigator//Account renewal//EN','BEGIN:VEVENT','UID:navigator-'+item.plan+'-'+stamp(end)+'@navigator','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(end),'SUMMARY:Navigator plan access ends','DESCRIPTION:Review plan renewal and save your local recovery file. No automatic renewal.','BEGIN:VALARM','TRIGGER:'+alarm,'ACTION:DISPLAY','DESCRIPTION:Review Navigator renewal','END:VALARM','END:VEVENT','END:VCALENDAR',''];const url=URL.createObjectURL(new Blob([lines.join('\r\n')],{type:'text/calendar'})),link=document.createElement('a');link.href=url;link.download='Navigator-plan-expiry.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};const reminder=document.createElement('p');reminder.className='g-mini';reminder.textContent='Calendar alert: '+({'-P7D':'seven days','-P1D':'one day','-PT1H':'one hour','-PT5M':'five minutes','PT0S':'at expiry'}[alarm])+(alarm==='PT0S'?'':' before access ends')+'. Import the file into your calendar; Navigator sends no automatic reminder.';row.append(title,p,a,button,reminder);if(!item.guided){const link=document.createElement('a');link.href='/#faq';link.className='btn btn-dark';link.textContent='Open knowledge resources';row.append(link);}list.append(row);}}
async function run(action){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await action()}catch(e){status.textContent=e.message;status.focus()}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=!ready&&b.id!=='account-refresh');resendState()}}
async function requestCode(){const email=$('account-otp-request').elements.email.value.trim();const r=await api('otp/request',{email});otpEmail=email;resendAt=Date.now()+r.retryAfter*1000;$('account-otp-request').hidden=true;$('account-otp-pending').hidden=false;$('account-otp-destination').textContent='Code requested for '+email;$('account-otp-verify').reset();status.textContent=r.message;$('account-otp-verify').elements.code.focus()}
$('account-otp-request').onsubmit=e=>{e.preventDefault();run(requestCode)};
$('account-otp-resend').onclick=()=>run(requestCode);
$('account-otp-change').onclick=()=>{$('account-otp-request').hidden=false;$('account-otp-pending').hidden=true;$('account-otp-verify').reset();otpEmail='';$('account-otp-request').elements.email.focus()};
$('account-otp-verify').onsubmit=e=>{e.preventDefault();run(async()=>{await api('otp/verify',{code:e.target.elements.code.value});e.target.reset();$('account-otp-request').hidden=false;otpEmail='';await load()})};
$('account-form').onsubmit=e=>{e.preventDefault();run(async()=>{const form=e.target;await api('login',{email:form.elements.email.value,password:form.elements.password.value});form.elements.password.value='';await load()})};
async function configure(){const c=await api('config');ready=!!(c.enabled&&c.configured);if(!ready){for(const id of ['account-login','account-profile','account-security','account-admin'])$(id).hidden=true;$('account-guest').hidden=false;throw Error('Account access is being configured. Public guidance remains available. Use Check access again to retry.');}await load();}
$('account-refresh').onclick=()=>run(configure);$('account-logout').onclick=()=>run(async()=>{try{await api('logout',{})}finally{$('account-secret').textContent='';$('account-secret-wrap').hidden=true;factorId='';$('account-otp-request').hidden=false;await load()}});
$('account-enrol').onclick=()=>run(async()=>{const r=await api('mfa/enrol',{});factorId=r.factorId;$('account-secret').textContent=r.secret;$('account-secret-wrap').hidden=false;status.textContent='Add the setup key in your authenticator app, then enter its code.'});
$('account-mfa').onsubmit=e=>{e.preventDefault();run(async()=>{if(!factorId)throw Error('Set up an authenticator first.');await api('mfa/verify',{factorId,code:e.target.elements.code.value});e.target.reset();$('account-secret').textContent='';$('account-secret-wrap').hidden=true;await load();status.textContent='Authenticator verified. Your active plan, if assigned, is shown above.'})};
async function adminList(){const id=$('admin-grant').elements.accountId.value;if(!id)return;const r=await api('admin/access',{accountId:id}),list=$('admin-access-list');list.replaceChildren();for(const item of r.result){const row=document.createElement('p'),text=document.createElement('span');text.textContent=item.plan+' · '+item.status+' · ends '+item.ends_at+' ';row.append(text);if(item.status==='active'){const button=document.createElement('button');button.type='button';button.className='btn btn-light';button.textContent='Revoke this access';button.onclick=()=>{if(!confirm('Revoke this customer’s '+item.plan+' access?'))return;run(async()=>{await api('admin/revoke',{accessId:item.access_id});await adminList();$('admin-result').textContent='Access revoked. Already downloaded documents remain on the customer’s device.'})};row.append(button)}list.append(row)}}
$('admin-lookup').onsubmit=e=>{e.preventDefault();run(async()=>{$('admin-grant').elements.accountId.value='';$('admin-access-list').replaceChildren();const r=await api('admin/lookup',{email:e.target.elements.email.value});if(!r.result.length)throw Error('No confirmed account found. Provision and confirm the customer account first.');const f=$('admin-grant').elements;f.accountId.value=r.result[0].account_id;f.verificationReference.value=crypto.randomUUID();f.startsAt.value=new Date().toISOString().slice(0,10);f.verified.checked=false;await adminList();$('admin-result').textContent='Confirmed account found. Verify purchase before assigning access.'})};
$('admin-grant').onsubmit=e=>{e.preventDefault();run(async()=>{const f=e.target.elements;if(!f.verified.checked)throw Error('Verify the purchase first.');await api('admin/grant',{accountId:f.accountId.value,plan:f.plan.value,startsAt:f.startsAt.value+'T00:00:00+05:30',endsAt:f.endsAt.value+'T00:00:00+05:30',verificationReference:f.verificationReference.value});f.verified.checked=false;f.verificationReference.value=crypto.randomUUID();await adminList();$('admin-result').textContent='Access assigned. Ask the customer to sign in with an email code and refresh access.'})};
 status.tabIndex=-1;run(configure);})();
